"""Pick the best hand(s) from a list of poker hands.

See https://en.wikipedia.org/wiki/List_of_poker_hands for an overview of
poker hands.
"""

_FACE_RANKS = {"J": 11, "Q": 12, "K": 13, "A": 14}


def _rank_value(rank):
    if rank == "10":
        return 10
    return _FACE_RANKS.get(rank, int(rank))


def _parse_hand(hand):
    """Return (rank_values, suits) for a whitespace-separated hand string."""
    values = []
    suits = []
    for card in hand.split():
        rank, suit = card[:-1], card[-1]
        values.append(_rank_value(rank))
        suits.append(suit)
    return values, suits


def _straight_high(values):
    """Return the highest rank of a straight, or None if not a straight.

    An ace may sit at either end: A-2-3-4-5 is a 5-high straight, but
    Q-K-A-2-3 is not a straight.
    """
    ordered = sorted(values)
    if len(set(ordered)) != 5:
        return None
    if ordered == [2, 3, 4, 5, 14]:
        return 5
    if ordered[-1] - ordered[0] == 4:
        return ordered[-1]
    return None


def _score(hand):
    """Return a comparable tuple ranking a hand.

    The first element is the category (higher is better); the remaining
    elements are tie-breakers, most significant first.
    """
    values, suits = _parse_hand(hand)
    straight_high = _straight_high(values)
    is_flush = len(set(suits)) == 1

    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    # (count, rank) groups, most numerous and highest ranked first.
    groups = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    shape = [count for count, _ in groups]

    if straight_high is not None and is_flush:
        return (8, straight_high)
    if shape[0] == 4:
        return (7, *(rank for _, rank in groups))
    if shape == [3, 2]:
        return (6, *(rank for _, rank in groups))
    if is_flush:
        return (5, *sorted(values, reverse=True))
    if straight_high is not None:
        return (4, straight_high)
    if shape[0] == 3:
        return (3, *(rank for _, rank in groups))
    if shape[0] == 2:
        return (2, *(rank for _, rank in groups))
    return (0, *sorted(values, reverse=True))


def best_hands(hands):
    """Return the winning hand(s) from a list of hands.

    Tied hands are all returned, in their original order.
    """
    scored = [(_score(hand), hand) for hand in hands]
    best = max(score for score, _ in scored)
    return [hand for score, hand in scored if score == best]

